import PageHeader from '@/components/page-header';
import { getOrders } from '@/lib/api';
const money = (n: number) => `৳${n.toLocaleString('en-US')}`;
export default async function Orders() { const orders = await getOrders(); return <><PageHeader eyebrow="Operations" title="Orders" action={<div className="rounded-full border border-line bg-white px-4 py-3 text-xs font-bold">All orders · {orders.length}</div>} /><div className="card overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[800px] text-left text-sm"><thead><tr className="bg-[#fafaf8] text-[10px] font-bold tracking-[.16em] text-muted uppercase"><th className="px-5 py-4">Order</th><th className="px-5 py-4">Customer</th><th className="px-5 py-4">Items</th><th className="px-5 py-4">Total</th><th className="px-5 py-4">Status</th><th className="px-5 py-4">Placed</th></tr></thead><tbody>{orders.map(o => <tr className="border-t border-line" key={o.id}><td className="px-5 py-4 font-bold">{o.orderNumber}</td><td className="px-5 py-4"><p className="font-bold">{o.customerName}</p><p className="text-xs text-muted">{o.phone} · {o.city}</p></td><td className="px-5 py-4 text-muted">{o.items?.reduce((a, i) => a + i.quantity, 0) || 0} pieces</td><td className="px-5 py-4 font-bold">{money(o.total)}</td><td className="px-5 py-4"><span className="rounded-full bg-[#fff4c9] px-2.5 py-1 text-[10px] font-bold uppercase">{o.status.toLowerCase()}</span></td><td className="px-5 py-4 text-muted">{new Date(o.createdAt).toLocaleDateString()}</td></tr>)}{orders.length === 0 && <tr><td className="px-5 py-14 text-center text-muted" colSpan={6}>No orders yet. Customer checkouts will appear here.</td></tr>}</tbody></table></div></div></> }
